import { ApiReference } from '@scalar/nextjs-api-reference'

// The spec is generated by the running Shopnex API (oRPC); point SHOPNEX_URL at your instance.
const shopnexUrl = process.env.SHOPNEX_URL ?? 'http://localhost:3000'

export const GET = ApiReference({
  url: `${shopnexUrl}/api/v1/openapi.json`,
  pageTitle: 'Shopnex API reference',
  servers: [{ url: shopnexUrl }],
})
